def resource_catalog(query='', category='', region='World', integration=''):
    from collections import Counter
    from app.intelligence.view import REGIONS
    states = {row[5] for row in RESOURCES}
    if (not isinstance(query, str) or len(query) > 500 or region not in REGIONS
            or not isinstance(category, str) or len(category) > 80
            or not isinstance(integration, str) or integration and integration not in states):
        raise ValueError('Use a bounded query and registered region.')
    terms = query.casefold().split()
    rows = [{'id': key, 'title': title, 'category': kind, 'region': area, 'url': url,
             'integration': state, 'notes': note, 'trust': 'untrusted_external_data'}
            for key, title, kind, area, url, state, note in RESOURCES
            if (not category or category == kind) and (not integration or integration == state)
            and (region == 'World' or area in ('World', region))
            and all(term in ' '.join((key, title, kind, area, note, state, url)).casefold() for term in terms)]
    return {'intelligence': True, 'resources': rows, 'count': len(rows),
            'total_registered': len(RESOURCES), 'categories': sorted({row[2] for row in RESOURCES}),
            'integration_counts': dict(Counter(row[5] for row in RESOURCES)),
            'basis': 'Curated publisher links are discovery resources, not proof of live coverage, configured API access or redistribution rights.'}
